#!/usr/bin/env node
// scaffold-file-upload-dropzone.js — v78 ship a drag-and-drop file upload
// component using react-dropzone. Pairs with scaffold-upload-pages (which
// emits the metadata form) — this is the dropzone primitive.
//
// Adds react-dropzone to deps.
// Idempotent. Marker: '// Generated by scaffold-file-upload-dropzone'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
  }
  if (!out.target) { console.error('Usage: scaffold-file-upload-dropzone --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-file-upload-dropzone — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-file-upload-dropzone/.test(existing) && !force) return { written: false, reason: 'exists-handauthored' };
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function ensureDep(pkgPath, deps, dryRun) {
  if (!fs.existsSync(pkgPath)) return { changed: false, reason: 'no-package-json' };
  var pkg; try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); } catch (_) { return { changed: false, reason: 'parse-error' }; }
  pkg.dependencies = pkg.dependencies || {};
  var added = [];
  Object.keys(deps).forEach(function (k) {
    if (!pkg.dependencies[k] && !(pkg.devDependencies || {})[k]) { pkg.dependencies[k] = deps[k]; added.push(k); }
  });
  if (!added.length) return { changed: false, reason: 'already-present' };
  if (dryRun) return { changed: false, reason: 'dry-run', added: added };
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return { changed: true, added: added };
}

var DROPZONE = [
  marker(),
  "import { useCallback, useState } from 'react';",
  "import { useDropzone, type DropzoneOptions } from 'react-dropzone';",
  "import { Upload, X } from 'lucide-react';",
  "import { cn } from '~/lib/utils';",
  "import { Button } from '~/components/ui/button';",
  '',
  'export interface FileDropzoneProps {',
  '  onFiles: (files: File[]) => void;',
  "  accept?: DropzoneOptions['accept'];",
  '  multiple?: boolean;',
  '  maxSize?: number;',
  '  className?: string;',
  '  testId?: string;',
  '}',
  '',
  "export function FileDropzone({ onFiles, accept, multiple = false, maxSize, className, testId = 'file-dropzone' }: FileDropzoneProps) {",
  '  const [files, setFiles] = useState<File[]>([]);',
  '  const onDrop = useCallback((accepted: File[]) => {',
  '    const next = multiple ? [...files, ...accepted] : accepted.slice(0, 1);',
  '    setFiles(next);',
  '    onFiles(next);',
  '  }, [files, multiple, onFiles]);',
  '  const { getRootProps, getInputProps, isDragActive } = useDropzone({ onDrop, accept, multiple, maxSize });',
  '  const remove = (idx: number) => {',
  '    const next = files.filter((_, i) => i !== idx);',
  '    setFiles(next); onFiles(next);',
  '  };',
  '  return (',
  '    <div className={cn(className)} data-testid={testId}>',
  '      <div',
  '        {...getRootProps()}',
  "        className={cn('rounded-md border-2 border-dashed p-6 text-center cursor-pointer transition-colors', isDragActive ? 'border-primary bg-primary/5' : 'border-input hover:border-primary/50')}",
  '        data-testid={`${testId}-zone`}',
  '      >',
  '        <input {...getInputProps()} data-testid={`${testId}-input`} />',
  '        <Upload className="mx-auto h-8 w-8 text-muted-foreground" />',
  "        <p className=\"mt-2 text-sm\">{isDragActive ? 'Drop here…' : 'Drag files here or click to browse'}</p>",
  '      </div>',
  '      {files.length > 0 && (',
  '        <ul className="mt-3 space-y-1">',
  '          {files.map((f, i) => (',
  '            <li key={`${f.name}-${i}`} className="flex items-center justify-between rounded border px-2 py-1 text-sm" data-testid={`${testId}-file-${i}`}>',
  '              <span className="truncate">{f.name} <span className="text-muted-foreground">({Math.round(f.size / 1024)} KB)</span></span>',
  '              <Button type="button" size="sm" variant="ghost" onClick={() => remove(i)} data-testid={`${testId}-remove-${i}`}><X className="h-4 w-4" /></Button>',
  '            </li>',
  '          ))}',
  '        </ul>',
  '      )}',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var r = writeIfManaged(path.join(args.target, 'app/components/ui/file-dropzone.tsx'), DROPZONE, args.force, args.dryRun);
  var d = ensureDep(path.join(args.target, 'package.json'), { 'react-dropzone': '^14.0.0' }, args.dryRun);
  console.log('scaffold-file-upload-dropzone: file-dropzone.tsx=' + (r.written ? 'wrote' : r.reason) + ' deps=' + (d.changed ? '+' + d.added.join(',') : d.reason));
}

main();
